/* From Uiverse.io by Praashoo7 - Tags: realistic, radio, traffic-lights */
/*Design Inspired by @ykadosh on Codepen*/

.__UIV_SCOPE__ .back {
  position: absolute;
  width: 16.6em;
  height: 6.5em;
  margin-top: -0.8em;
  margin-left: -0.77em;
  border-radius: 70px;
  box-shadow: rgba(0, 0, 0, 0.4) 0px 2px 2px, rgba(0, 0, 0, 0.3) 0px 7px 13px -3px, rgba(0, 0, 0, 0.2) 0px -1px 0px inset;
  background-color: #171717;
  z-index: -1;
}

.__UIV_SCOPE__ .main {
  display: flex;
}

.__UIV_SCOPE__ .switch {
  display: block;
  position: relative;
  background-color: black;
  width: 70px;
  height: 70px;
  box-shadow: 0 0 10px 2px rgba(0, 0, 0, 0.2), 0 0 1px 2px black, inset 0 2px 2px -2px white, inset 0 0 2px 5px #47434c, inset 0 0 2px 22px black;
  border-radius: 50%;
  padding: 20px;
  margin: 5px;
}

.__UIV_SCOPE__ .switch input {
  display: none;
}

.__UIV_SCOPE__ .switch input:checked + .button .light {
  animation: flicker 0.2s infinite 0.3s;
}

.__UIV_SCOPE__ .switch input:checked + .button .shine {
  opacity: 1;
}

.__UIV_SCOPE__ .switch input:checked + .button .shadow {
  opacity: 0;
}

.__UIV_SCOPE__ .switch .button {
  transition: all 0.3s cubic-bezier(1, 0, 1, 1);
  background-color: #9b0621;
  width: 55px;
  height: 55px;
  border-radius: 50%;
  position: relative;
  left: -0.75em;
  top: -0.75em;
  cursor: pointer;
}

.__UIV_SCOPE__ .switch .light {
  opacity: 0;
  animation: light-off 1s;
  position: absolute;
  width: 100%;
  height: 100%;
  background-image: radial-gradient(#ffc97e, #ff1818 40%, transparent 70%);
}

.__UIV_SCOPE__ .switch .dots {
  position: absolute;
  width: 100%;
  height: 100%;
  background-image: radial-gradient(transparent 30%, rgba(101, 0, 0, 0.7) 70%);
  background-size: 10px 10px;
  border-radius: 50%;
}

@keyframes flicker {
  0% {
    opacity: 1;
  }

  80% {
    opacity: 0.8;
  }

  100% {
    opacity: 1;
  }
}

@keyframes light-off {
  0% {
    opacity: 1;
  }

  80% {
    opacity: 0;
  }
}

